175	  const saved=Object.entries(personalState).filter(([,item])=>item.saved);
176	  if(!saved.length){const empty=document.createElement('p');empty.className='hint';empty.textContent='No personal info saved';el('personal-list').append(empty);}
177	  for(const [kind,item] of saved){
178	    const row=document.createElement('article');row.className='personal-row';
179	    const text=document.createElement('div'),label=document.createElement('strong'),detail=document.createElement('small');
180	    label.textContent=item.label;detail.textContent=item.summary;text.append(label,detail);
181	    const edit=document.createElement('button');edit.type='button';edit.textContent='Edit';edit.setAttribute('aria-label','Edit '+personalLabels[kind]);edit.onclick=()=>openPersonal(kind);
182	    row.append(text,edit);el('personal-list').append(row);
183	  }
184	}
185	function clearPersonalForm(){el('personal-form').reset();for(const fields of Object.values(personalFields))for(const id of Object.values(fields))el(id).value='';}
186	async function openPersonal(kind){
187	  personalKind=kind;clearPersonalForm();el('personal-add').open=false;el('personal-error').hidden=true;
188	  const editing=Boolean(personalState[kind]?.saved);el('personal-title').textContent=(editing?'Edit ':'Add ')+personalLabels[kind];
189	  for(const key of Object.keys(personalFields)){
190	    el('personal-'+key+'-fields').hidden=key!==kind;
191	    for(const [field,id] of Object.entries(personalFields[key]))el(id).required=key===kind&&!['middle_name','family_name','address_line2','state','country_code'].includes(field);
192	  }
193	  if(kind==='dob'){const today=new Date();el('personal-dob').max=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');}
194	  el('remove-personal').hidden=!editing;el('save-personal').disabled=editing;el('personal-dialog').showModal();
195	  if(editing){try{const result=await api('/api/personal/details',{kind});for(const [field,id] of Object.entries(personalFields[kind]))el(id).value=result.fields[field]||'';}
196	    catch(error){el('personal-error').textContent=error.message;el('personal-error').hidden=false;return;}}
197	  el('save-personal').disabled=false;el(Object.values(personalFields[kind])[0]).focus();
198	}
199	for(const button of document.querySelectorAll('[data-add-personal]'))button.onclick=()=>openPersonal(button.dataset.addPersonal);
200	el('close-personal').onclick=()=>el('personal-dialog').close();
