206	    el('vault-message').textContent='Your '+personalLabels[personalKind]+' is saved for repeat use.';el('vault-message').hidden=false;}
207	  catch(error){el('personal-error').textContent=error.message;el('personal-error').hidden=false;}finally{el('save-personal').disabled=false;}
208	};
209	el('remove-personal').onclick=async()=>{
210	  if(!confirm('Remove your '+personalLabels[personalKind]+'? Existing website logins keep their own saved details.'))return;
211	  el('remove-personal').disabled=true;
212	  try{const result=await api('/api/personal/remove',{kind:personalKind});renderPersonalInfo(result.personal_info);el('personal-dialog').close();}
213	  catch(error){el('personal-error').textContent=error.message;el('personal-error').hidden=false;}finally{el('remove-personal').disabled=false;}
214	};

